layer.css:
@import url("https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@500&display=swap");
[data-ryt="pitch"] { color: rgb(102, 102, 102); background-color: var(--ryt-bg); border-right: 2px solid rgb(255, 166, 140); border-left: 5px solid rgb(255, 166, 140); border-radius: 0px; box-shadow: rgb(204, 204, 204) 2px 2px 8px 0px; font-family: Georgia, serif; font-size: 17.5px; font-weight: 700; font-style: italic; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(102, 102, 102); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 15px; padding-right: 20px; padding-bottom: 15px; padding-left: 45px; transition: all; border-top: none; border-bottom: none; position: relative }
article[data-ryt="rec-card"] { border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 26px; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; line-height: 1.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: #c87140; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.111; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(237, 129, 67); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-bg) 25%, transparent) 0px 1px 0px; transition: all }
[data-ryt="header"] { background-image: linear-gradient(var(--ryt-bg) 0px, var(--ryt-header-bg) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat-x; border-bottom: 1px solid rgb(231, 231, 231); box-shadow: color-mix(in srgb, var(--ryt-bg) 15%, transparent) 0px 1px 0px 0px inset, rgba(0, 0, 0, 0.075) 0px 1px 5px 0px; border-top: none }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: color-mix(in srgb, var(--ryt-bg) 25%, transparent) 0px 1px 0px; padding-top: 15px; padding-right: 15px; padding-bottom: 15px; padding-left: 15px; transition: all }
[data-ryt="button"] { color: var(--ryt-text); background-color: var(--ryt-bg); background-image: linear-gradient(var(--ryt-bg) 0px, rgb(224, 224, 224) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat-x; border-top: 1px solid rgb(204, 204, 204); border-right: 1px solid rgb(204, 204, 204); border-bottom: 1px solid rgb(204, 204, 204); border-left: 1px solid rgb(204, 204, 204); border-radius: 3px; box-shadow: color-mix(in srgb, var(--ryt-bg) 15%, transparent) 0px 1px 0px 0px inset, rgba(0, 0, 0, 0.075) 0px 1px 1px 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: capitalize; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-bg) 0px 1px 0px; padding-top: 1px; padding-right: 5px; padding-bottom: 1px; padding-left: 5px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-text); background-color: var(--ryt-bg); background-image: linear-gradient(var(--ryt-bg) 0px, rgb(224, 224, 224) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat-x; border-top: 1px solid rgb(204, 204, 204); border-right: 1px solid rgb(204, 204, 204); border-bottom: 1px solid rgb(204, 204, 204); border-left: 1px solid rgb(204, 204, 204); border-radius: 3px; box-shadow: color-mix(in srgb, var(--ryt-bg) 15%, transparent) 0px 1px 0px 0px inset, rgba(0, 0, 0, 0.075) 0px 1px 1px 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: capitalize; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-bg) 0px 1px 0px; padding-top: 1px; padding-right: 5px; padding-bottom: 1px; padding-left: 5px; transition: all }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.571; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #858585; font-family: var(--ryt-font-heading); font-size: 12px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(128, 128, 128); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 500; font-style: normal; line-height: 1.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(128, 128, 128); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="review"]:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-text); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-text); background-color: rgb(230, 230, 230); border-top-color: rgb(173, 173, 173); border-right-color: rgb(173, 173, 173); border-bottom-color: rgb(173, 173, 173); border-left-color: rgb(173, 173, 173); background-color: rgb(224, 224, 224) }
[data-ryt="button"]:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-text); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: var(--ryt-text); background-color: rgb(230, 230, 230); border-top-color: rgb(173, 173, 173); border-right-color: rgb(173, 173, 173); border-bottom-color: rgb(173, 173, 173); border-left-color: rgb(173, 173, 173); background-color: rgb(224, 224, 224); color: rgb(237, 129, 67) }
[data-ryt="nav"] a:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(238, 238, 238); color: var(--ryt-text); background-color: transparent }
[data-ryt="brand"]:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(94, 94, 94); background-color: transparent }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { outline-color: initial; color: rgb(35, 82, 124); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
article[data-ryt="rec-card"]::before { content: " "; display: table; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
article[data-ryt="rec-card"]::after { content: " "; display: table; color: var(--ryt-text); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.429; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="pitch"]::before { content: "“"; display: block; position: absolute; width: 30px; height: 72px; color: rgb(153, 153, 153); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: Georgia, serif; font-size: 60px; font-weight: 700; font-style: italic; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(153, 153, 153); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(153, 153, 153); top: 5px; left: 10px }
[data-ryt="pitch"]::after { content: ""; display: inline; color: rgb(102, 102, 102); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: Georgia, serif; font-size: 17.5px; font-weight: 700; font-style: italic; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(102, 102, 102); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(102, 102, 102) }
